class IdentifyCommitteeModule(dspy.Module):
    def __init__(self):
        super().__init__()
        self.predict = dspy.Predict(dspy.Signature('email_body: str -> committee: str', "Identify the political committee that sponsored a fundraising email.\n\nThe committee's name is present in the email text itself, so most emails can be resolved\ndeterministically in code with no model call; reserve a model call only as a fallback for\nemails the code cannot resolve."))

    def forward(self, **inputs):
        result = self.predict(**inputs)
        return dspy.Prediction(committee=result.committee)
